import React, { ForwardedRef, useContext } from 'react';
import { OriginIconProps } from '../type';
import { Context } from '../context';

function IconOtherPluginComponent(props: OriginIconProps, ref: ForwardedRef<SVGSVGElement>) {
    const { prefix: prefixFromContext } = useContext(Context);
    const { className = '', prefix: prefixFromProps, width = '1em', height = '1em', useCurrentColor = true, spin, ...rest } = props;

    const prefix = prefixFromProps || prefixFromContext || 'force';
    const loadingKls = spin ? ` ${prefix}-icon-loading` : '';
    return <svg className={`${prefix}-icon ${prefix}-icon-Other_Plugin${loadingKls} ${className}`} width={width} height={height} viewBox="0 0 49 48" fill={useCurrentColor ? 'currentColor' : '#000'} xmlns="http://www.w3.org/2000/svg" {...rest} ref={ref}><rect x="4.759" y="4" width="18" height="18" rx="1.6"/><rect x="26.759" y="26" width="18" height="18" rx="1.6"/><rect x="3.716" y="34.562" width="14.328" height="14.328" rx="1.6" transform="rotate(-45 3.716 34.562)"/><circle opacity=".5" cx="35.759" cy="13" r="9"/></svg>;
}

const IconOtherPlugin = React.forwardRef(IconOtherPluginComponent);
export default IconOtherPlugin;
